(7631967, 1237170, 92512, '<td valign="top">just above third row of windows. Great abstract with the scaffolding.</td>', 'just above third row of windows. Great abstract with the scaffolding.', '2019-06-04 23:00:29.000000', NULL, 1),
(7631968, 1237068, 92512, '<td valign="top">Just right of the third tree from the right.</td>', 'Just right of the third tree from the right.', '2019-06-04 23:01:29.000000', NULL, 1),
(7631970, 1237183, 173844, '<td valign="top">In this vast expanse I see but the one tiny person crossing the street on the left.  Perfectly observed, moving in the seeming loneliness of the city, from the outskirts in.  I like the kind of triangular composition, with the viewer at the apex.  Aside from the Waldo business, a stellar cityscape.<br/>Personal favorite of the challenge.</td>', 'In this vast expanse I see but the one tiny person crossing the street on the left.  Perfectly observed, moving in the seeming loneliness of the city, from the outskirts in.  I like the kind of triangular composition, with the viewer at the apex.  Aside from the Waldo business, a stellar cityscape.Personal favorite of the challenge.', '2019-06-04 23:27:37.000000', NULL, 1),
(7631972, 1236830, 173844, '<td valign="top">Lovely, dusky nightscape.  The starbursts seem less affectation than magic.  Nice velvety feel.  Waldo is clear and apparent, but appears as if by sleight of hand.  Handsome.</td>', 'Lovely, dusky nightscape.  The starbursts seem less affectation than magic.  Nice velvety feel.  Waldo is clear and apparent, but appears as if by sleight of hand.  Handsome.', '2019-06-04 23:32:18.000000', NULL, 1),
(7631973, 1237140, 173844, '<td valign="top">Almost lost in the veils of dazzle is an elusive Waldo.  Beautifully played.</td>', 'Almost lost in the veils of dazzle is an elusive Waldo.  Beautifully played.', '2019-06-04 23:34:55.000000', NULL, 1),
(7631975, 1237115, 173844, '<td valign="top">Got lost in the beauty of the scene and almost forgot about Waldo, that tiny artifact of humanity on the right edge.  Fine image.</td>', 'Got lost in the beauty of the scene and almost forgot about Waldo, that tiny artifact of humanity on the right edge.  Fine image.', '2019-06-04 23:43:53.000000', NULL, 1),
(7631977, 1237068, 173844, '<td valign="top">Dreamy and bucolic, a moment conjured from the middle ages.  Lovely palette.  I love the slight blur, the shift in time.</td>', 'Dreamy and bucolic, a moment conjured from the middle ages.  Lovely palette.  I love the slight blur, the shift in time.', '2019-06-04 23:47:16.000000', NULL, 1),
(7631978, 1237058, 173844, '<td valign="top">Beautiful blue image.  Very neat that one lamp is out while the other one spills over a modestly discordant Waldo.  So there is a reason to visit New Jersey.  Come on, it''s a joke.</td>', 'Beautiful blue image.  Very neat that one lamp is out while the other one spills over a modestly discordant Waldo.  So there is a reason to visit New Jersey.  Come on, it''s a joke.', '2019-06-04 23:52:44.000000', NULL, 1),
